editorMethods.#expandPasteMarkers:
#expandPasteMarkers(text: string): string {
	const sources: string[] = [];
	for (const pasteId of this.#pastes.keys()) {
		sources.push(`\\[Paste #${pasteId}(?:, (?:\\+\\d+ lines|\\d+ chars))?\\]`);
	}
	const labels = [...this.#atoms.keys()].sort((a, b) => b.length - a.length);
	for (const label of labels) sources.push(RegExp.escape(label));
	if (sources.length === 0) return text;
	const markerRegex = new RegExp(sources.join("|"), "g");
	return text.replace(markerRegex, match => {
		const paste = /^\[Paste #(\d+)/.exec(match);
		if (paste) return this.#pastes.get(Number(paste[1])) ?? match;
		return this.#atoms.get(match) ?? match;
	});
}

editorMethods.#getAtomicTokenRe:
#getAtomicTokenRe(): RegExp | undefined {
	const pattern = this.atomicTokenPattern;
	if (pattern === undefined) {
		this.#atomicTokenSource = undefined;
		this.#atomicTokenRe = undefined;
		return undefined;
	}
	if (pattern.source !== this.#atomicTokenSource) {
		this.#atomicTokenSource = pattern.source;
		this.#atomicTokenRe = new RegExp(
			pattern.source,
			pattern.flags.includes("g") ? pattern.flags : `${pattern.flags}g`,
		);
	}
	return this.#atomicTokenRe;
}

editorMethods.#atomicTokenAt:
#atomicTokenAt(line: string, col: number): { start: number; end: number } | undefined {
	const re = this.#getAtomicTokenRe();
	if (re === undefined) return undefined;
	re.lastIndex = 0;
	for (;;) {
		const match = re.exec(line);
		if (match === null) break;
		if (match[0].length === 0) {
			re.lastIndex = match.index + 1;
			continue;
		}
		const start = match.index;
		const end = start + match[0].length;
		if (col < start) break;
		if (col < end) return { start, end };
	}
	return undefined;
}

editorMethods.#expandRangeOverAtomicTokens:
#expandRangeOverAtomicTokens(line: string, start: number, end: number): { start: number; end: number } {
	const startToken = this.#atomicTokenAt(line, start);
	if (startToken !== undefined && startToken.start < start) {
		start = startToken.start;
	}
	if (end > start) {
		const endToken = this.#atomicTokenAt(line, end - 1);
		if (endToken !== undefined && endToken.end > end) {
			end = endToken.end;
		}
	}
	return { start, end };
}

editorMethods.registerAtom:
registerAtom(label: string, expansion: string): void {
	this.#atoms.set(label, expansion);
	this.#atomsRevision++;
}

skillFunctions.startsWithLocalExecutionPrefix:
function startsWithLocalExecutionPrefix(trimmedStart: string): boolean {
	if (trimmedStart.startsWith("!")) return true;
	if (trimmedStart.charCodeAt(0) !== 36 /* $ */) return false;
	if (trimmedStart.charCodeAt(1) === 123 /* { */) return false;
	const sigilLength = trimmedStart.charCodeAt(1) === 36 /* $ */ ? 2 : 1;
	const next = trimmedStart.charCodeAt(sigilLength);
	if (Number.isNaN(next)) return true;
	return next === 32 /* space */ || next === 9 /* tab */ || next === 10 /* LF */ || next === 13; /* CR */
}

skillFunctions.allowsSkillTokens:
export function allowsSkillTokens(text: string): boolean {
	const trimmedStart = text.trimStart();
	if (trimmedStart.startsWith("/skill:")) return true;
	if (trimmedStart.startsWith("/")) return false;
	return !startsWithLocalExecutionPrefix(trimmedStart);
}

skillFunctions.collapseSkillTokens:
export function collapseSkillTokens(
	text: string,
	isKnown: (name: string) => boolean,
	register: (label: string, expansion: string) => void,
): string {
	if (!text.includes("/skill:") || !allowsSkillTokens(text)) return text;
	SKILL_TOKEN_RE.lastIndex = 0;
	return text.replace(SKILL_TOKEN_RE, (match, delimiter: string, name: string) => {
		if (!isKnown(name)) return match;
		const label = skillChipLabel(name);
		register(label, skillToken(name));
		return `${delimiter}${label}`;
	});
}
